  +name : string
  +address : string
}

class Employee extends Person {
}

class Owner extends Person {
  +phone : string
}

class Service {
  +kms : int
  +workHours : float
  +admissionDate : date
  +finishDate : date
}

class Car {
  +licensePlate : string
  +make : string
  +model : string
  +color : string
}

class PartAcc {
  +category : string
  +serialNumber : string
  +price : double
}

class CarModel {}

Owner "1" -- "*" Car : owns
Car "1" -- "*" Service : undergoes
Employee "1" -- "*" Service : is responsible for
Service "*" -- "1..*" PartAcc : fits
PartAcc "*" -- "1" CarModel : fits in
Car "*" -- "1" CarModel : is a model of

@enduml

